//! # atoms-validation
//!
//! Cross-crate scientific validation tests.
//!
//! This crate contains no production code. It exists so that the scientific
//! acceptance criteria of a milestone can be checked against the whole
//! workspace at once, and so that independent reference data can live next to
//! the tests that consume it.
//!
//! ## Test binaries
//!
//! * `reference_values` — comparison against reference values generated by an
//!   independent implementation (SciPy) via
//!   `python/tests/generate_reference_values.py`.
//! * `physics` — analytically known physical results.
//! * `numerical` — convergence rates, sampling distributions, reproducibility.
//! * `integration` — end-to-end pipelines and architectural invariants.
//!
//! ## Reference data
//!
//! `docs/validation/reference-values.csv` is generated, never hand-written. To
//! regenerate it:
//!
//! ```text
//! python python/tests/generate_reference_values.py
//! ```
//!
//! The generator uses only `numpy` and `scipy`, i.e. it shares no code with the
//! Rust implementation under test.

/// Raw CSV rows of the reference-value file.
pub const REFERENCE_VALUES_CSV: &str =
    include_str!("../../../docs/validation/reference-values.csv");

/// Expected number of data rows in the reference file, used to detect a
/// truncated or partially regenerated file.
pub const EXPECTED_HARMONIC_ROWS: usize = 252;
/// Expected number of radial rows.
pub const EXPECTED_RADIAL_ROWS: usize = 288;
/// Expected number of density rows.
pub const EXPECTED_DENSITY_ROWS: usize = 108;
/// Expected number of Laguerre rows (exact rational arithmetic reference).
pub const EXPECTED_LAGUERRE_ROWS: usize = 84;

/// One parsed reference row.
#[derive(Debug, Clone)]
pub struct ReferenceRow {
    /// Row kind: `"harmonic"`, `"radial"`, `"density"` or `"laguerre"`.
    pub kind: String,
    /// Raw string fields 1..=7.
    pub fields: [String; 7],
}

impl ReferenceRow {
    /// Parse field `i` as `f64`.
    pub fn number(&self, i: usize) -> f64 {
        self.fields[i]
            .trim()
            .parse::<f64>()
            .unwrap_or_else(|_| panic!("field {i} of {:?} is not a number", self.fields[i]))
    }

    /// Parse field `i` as `u32`.
    pub fn uint(&self, i: usize) -> u32 {
        self.fields[i]
            .trim()
            .parse::<u32>()
            .unwrap_or_else(|_| panic!("field {i} of {:?} is not an integer", self.fields[i]))
    }

    /// Parse field `i` as `i32`.
    pub fn int(&self, i: usize) -> i32 {
        self.fields[i]
            .trim()
            .parse::<i32>()
            .unwrap_or_else(|_| panic!("field {i} of {:?} is not an integer", self.fields[i]))
    }
}

/// Parse the committed reference-value file.
///
/// The file is simple, well-formed CSV: eight columns, no embedded commas, no
/// quoting. Parsing it by hand avoids a CSV dependency in a test-only crate.
pub fn reference_rows() -> Vec<ReferenceRow> {
    let mut rows = Vec::new();
    for (lineno, line) in REFERENCE_VALUES_CSV.lines().enumerate() {
        let line = line.trim_end_matches('\r');
        if line.is_empty() {
            continue;
        }
        if lineno == 0 {
            assert_eq!(
                line, "kind,a,b,c,d,e,f,g",
                "reference-values.csv has an unexpected header; regenerate it"
            );
            continue;
        }
        let parts: Vec<&str> = line.split(',').collect();
        assert_eq!(
            parts.len(),
            8,
            "line {} has {} columns, expected 8",
            lineno + 1,
            parts.len()
        );
        rows.push(ReferenceRow {
            kind: parts[0].to_string(),
            fields: [
                parts[1].to_string(),
                parts[2].to_string(),
                parts[3].to_string(),
                parts[4].to_string(),
                parts[5].to_string(),
                parts[6].to_string(),
                parts[7].to_string(),
            ],
        });
    }
    rows
}

/// Rows of one kind.
pub fn rows_of_kind(kind: &str) -> Vec<ReferenceRow> {
    reference_rows()
        .into_iter()
        .filter(|r| r.kind == kind)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reference_file_is_present_and_complete() {
        let rows = reference_rows();
        assert_eq!(rows_of_kind("harmonic").len(), EXPECTED_HARMONIC_ROWS);
        assert_eq!(rows_of_kind("radial").len(), EXPECTED_RADIAL_ROWS);
        assert_eq!(rows_of_kind("density").len(), EXPECTED_DENSITY_ROWS);
        assert_eq!(rows_of_kind("laguerre").len(), EXPECTED_LAGUERRE_ROWS);
        assert_eq!(
            rows.len(),
            EXPECTED_HARMONIC_ROWS
                + EXPECTED_RADIAL_ROWS
                + EXPECTED_DENSITY_ROWS
                + EXPECTED_LAGUERRE_ROWS
        );
    }

    #[test]
    fn reference_file_contains_only_finite_numbers() {
        for r in reference_rows() {
            for i in 0..7 {
                let f = &r.fields[i];
                if f.trim().is_empty() {
                    continue;
                }
                let v: f64 = f.trim().parse().expect("finite number");
                assert!(v.is_finite(), "row {:?} field {i} is {v}", r.kind);
            }
        }
    }
}
